                                                        <summary class="e-n-accordion-item-title" data-accordion-index="2" tabindex="-1" aria-expanded="false" aria-controls="e-n-accordion-item-1511">
                                                            <span class='e-n-accordion-item-title-header'>
                                                                <h5 class="e-n-accordion-item-title-text"> Who will I be working with directly? </h5>
                                                            </span>
                                                            <span class='e-n-accordion-item-title-icon'>
                                                                <span class='e-opened'><svg aria-hidden="true" class="e-font-icon-svg e-fas-minus" viewBox="0 0 448 512" xmlns="http://www.w3.org/2000/svg">
